func TestDisableQueueGroup(t *testing.T) {
	withServer(t, func(t *testing.T, nc *nats.Conn) {
		wg := sync.WaitGroup{}

		// Create 5 service responders.
		config := micro.Config{
			Name:        "CoolAddService",
			Version:     "0.1.0",
			Description: "Add things together",
			Metadata:    map[string]string{"basic": "metadata"},
			Endpoint: &micro.EndpointConfig{
				Subject: "svc.add",
				Handler: micro.HandlerFunc(func(r micro.Request) {
					r.Respond(nil)
					wg.Done()
				}),
			},
			QueueGroupDisabled: true,
		}

		for range 10 {
			srv, err := micro.AddService(nc, config)
			if err != nil {
				t.Fatalf("Unexpected error: %v", err)
			}
			defer srv.Stop()
		}
		wg.Add(10)
		// Send a request to the service.
		if err := nc.PublishRequest("svc.add", "rply", []byte("req")); err != nil {
			t.Fatalf("Unexpected error: %v", err)
		}
		wg.Wait()
	})
}

func (r *request) Error(code, description string, data []byte, opts ...RespondOpt) error {
	if code == "" {
		return fmt.Errorf("%w: error code", ErrArgRequired)
	}
	if description == "" {
		return fmt.Errorf("%w: description", ErrArgRequired)
	}
	response := &nats.Msg{
		Header: nats.Header{
			ErrorHeader:     []string{description},
			ErrorCodeHeader: []string{code},
		},
	}
	for _, opt := range opts {
		opt(response)
	}

	response.Data = data
	if err := r.msg.RespondMsg(response); err != nil {
		r.respondError = err
		return err
	}
	r.respondError = &serviceError{
		Code:        code,
		Description: description,
	}

	return nil
}

func (h Headers) Values(key string) []string {
	return nats.Header(h).Values(key)
}

func TestNATSErrorUnwrap(t *testing.T) {
	baseErr := errors.New("base error")
	natsErr := &NATSError{
		Subject:     "test.subject",
		Description: "test description",
		err:         baseErr,
	}

	unwrapped := errors.Unwrap(natsErr)
	if unwrapped != baseErr {
		t.Errorf("Unwrap() = %v, want %v", unwrapped, baseErr)
	}

	// Test with nil underlying error
	natsErr2 := &NATSError{
		Subject:     "test.subject",
		Description: "test description",
	}
	if errors.Unwrap(natsErr2) != nil {
		t.Errorf("Unwrap() with nil err should return nil")
	}
}

