func TestMonitoringHandlers(t *testing.T) {
	withServer(t, func(t *testing.T, nc *nats.Conn) {
		asyncErr := make(chan struct{})
		errHandler := func(s micro.Service, n *micro.NATSError) {
			asyncErr <- struct{}{}
		}

		config := micro.Config{
			Name:         "test_service",
			Version:      "0.1.0",
			ErrorHandler: errHandler,
			Endpoint: &micro.EndpointConfig{
				Subject:  "test.func",
				Handler:  micro.HandlerFunc(func(r micro.Request) {}),
				Metadata: map[string]string{"basic": "schema"},
			},
		}
		srv, err := micro.AddService(nc, config)
		if err != nil {
			t.Fatalf("Unexpected error: %v", err)
		}
		defer func() {
			srv.Stop()
			if !srv.Stopped() {
				t.Fatalf("Expected service to be stopped")
			}
		}()

		info := srv.Info()

		tests := []struct {
			name             string
			subject          string
			withError        bool
			expectedResponse any
		}{
			{
				name:    "PING all",
				subject: "$SRV.PING",
				expectedResponse: micro.Ping{
					Type: micro.PingResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
				},
			},
			{
				name:    "PING name",
				subject: "$SRV.PING.test_service",
				expectedResponse: micro.Ping{
					Type: micro.PingResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
				},
			},
			{
				name:    "PING ID",
				subject: fmt.Sprintf("$SRV.PING.test_service.%s", info.ID),
				expectedResponse: micro.Ping{
					Type: micro.PingResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
				},
			},
			{
				name:    "INFO all",
				subject: "$SRV.INFO",
				expectedResponse: micro.Info{
					Type: micro.InfoResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
					Endpoints: []micro.EndpointInfo{
						{
							Name:       "default",
							Subject:    "test.func",
							QueueGroup: "q",
							Metadata:   map[string]string{"basic": "schema"},
						},
					},
				},
			},
			{
				name:    "INFO name",
				subject: "$SRV.INFO.test_service",
				expectedResponse: micro.Info{
					Type: micro.InfoResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
					Endpoints: []micro.EndpointInfo{
						{
							Name:       "default",
							Subject:    "test.func",
							QueueGroup: "q",
							Metadata:   map[string]string{"basic": "schema"},
						},
					},
				},
			},
			{
				name:    "INFO ID",
				subject: fmt.Sprintf("$SRV.INFO.test_service.%s", info.ID),
				expectedResponse: micro.Info{
					Type: micro.InfoResponseType,
					ServiceIdentity: micro.ServiceIdentity{
						Name:     "test_service",
						Version:  "0.1.0",
						ID:       info.ID,
						Metadata: map[string]string{},
					},
					Endpoints: []micro.EndpointInfo{
						{
							Name:       "default",
							Subject:    "test.func",
							QueueGroup: "q",
							Metadata:   map[string]string{"basic": "schema"},
						},
					},
				},
			},
			{
				name:      "PING error",
				subject:   "$SRV.PING",
				withError: true,
			},
			{
				name:      "INFO error",
				subject:   "$SRV.INFO",
				withError: true,
			},
			{
				name:      "STATS error",
				subject:   "$SRV.STATS",
				withError: true,
			},
		}

		for _, test := range tests {
			t.Run(test.name, func(t *testing.T) {
				if test.withError {
					// use publish instead of request, so Respond will fail inside the handler
					if err := nc.Publish(test.subject, nil); err != nil {
						t.Fatalf("Unexpected error: %v", err)
					}
					select {
					case <-asyncErr:
						return
					case <-time.After(1 * time.Second):
						t.Fatalf("Timeout waiting for async error")
					}
					return
				}

				resp, err := nc.Request(test.subject, nil, 1*time.Second)
				if err != nil {
					t.Fatalf("Unexpected error: %v", err)
				}

				respMap := make(map[string]any)
				if err := json.Unmarshal(resp.Data, &respMap); err != nil {
					t.Fatalf("Unexpected error: %v", err)
				}
				expectedResponseJSON, err := json.Marshal(test.expectedResponse)
				if err != nil {
					t.Fatalf("Unexpected error: %v", err)
				}
				expectedRespMap := make(map[string]any)
				if err := json.Unmarshal(expectedResponseJSON, &expectedRespMap); err != nil {
					t.Fatalf("Unexpected error: %v", err)
				}
				if !reflect.DeepEqual(respMap, expectedRespMap) {
					t.Fatalf("Invalid response; want: %+v; got: %+v", expectedRespMap, respMap)
				}
			})
		}
	})
}

func (s *service) AddGroup(name string, opts ...GroupOpt) Group {
	var o groupOpts
	for _, opt := range opts {
		opt(&o)
	}
	queueGroup, noQueue := resolveQueueGroup(o.queueGroup, s.Config.QueueGroup, o.qgDisabled, s.Config.QueueGroupDisabled)
	return &group{
		service:            s,
		prefix:             name,
		queueGroup:         queueGroup,
		queueGroupDisabled: noQueue,
	}
}

EndpointConfig struct {
	// Subject on which the endpoint is registered.
	Subject string

	// Handler used by the endpoint.
	Handler Handler

	// Metadata annotates the service
	Metadata map[string]string `json:"metadata,omitempty"`

	// QueueGroup can be used to override the default queue group name.
	QueueGroup string `json:"queue_group"`

	// QueueGroupDisabled disables the queue group for the endpoint.
	QueueGroupDisabled bool `json:"queue_group_disabled"`
}

func (g *group) AddEndpoint(name string, handler Handler, opts ...EndpointOpt) error {
	var options endpointOpts
	for _, opt := range opts {
		if err := opt(&options); err != nil {
			return err
		}
	}
	subject := name
	if options.subject != "" {
		subject = options.subject
	}
	endpointSubject := fmt.Sprintf("%s.%s", g.prefix, subject)
	if g.prefix == "" {
		endpointSubject = subject
	}
	queueGroup, noQueue := resolveQueueGroup(options.queueGroup, g.queueGroup, options.qgDisabled, g.queueGroupDisabled)

	return addEndpoint(g.service, name, endpointSubject, handler, options.metadata, queueGroup, noQueue, options.msgLimit, options.bytesLimit)
}

