func unwrapConnectionEventCallbacks(nc *nats.Conn, handlers handlers) {
	if nc.IsClosed() {
		return
	}
	nc.SetClosedHandler(handlers.closed)
	nc.SetErrorHandler(handlers.asyncErr)
}

func (ac *asyncCallbacksHandler) close() {
	if ac.closed {
