		log.Fatal(err)
	}
	defer nc.Close()

	config := micro.Config{
		Name:    "EchoService",
		Version: "0.1.0",
	}

	srv, _ := micro.AddService(nc, config)

	// reset endpoint stats on this service
	srv.Reset()

	empty := micro.Stats{
		ServiceIdentity: srv.Info().ServiceIdentity,
	}
	if !reflect.DeepEqual(srv.Stats(), empty) {
		log.Fatal("Expected endpoint stats to be empty")
	}
}

